const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert/strict');
const vm = require('node:vm');

// Buildless runtime: keep the existing operations document self-contained for file:// and HTTP.
const root = path.resolve('dist');
let document = fs.readFileSync(path.join(root, 'aiops-extensions.html'), 'utf8');
document = document.replace(/<link rel="stylesheet" href="([^"]+)"\s*\/?>/g, (_, ref) =>
  '<style>\n' + fs.readFileSync(path.resolve(root, ref.split('?')[0]), 'utf8') + '\n</style>');
document = document.replace(/<script src="([^"]+)"\s*><\/script>/g, (_, ref) =>
  '<script>\n' + fs.readFileSync(path.resolve(root, ref.split('?')[0]), 'utf8').replace(/<\/script/gi, '<\\/script') + '\n</script>');
document = document.replace('<head>', '<head><base href="__AIOPS_BASE__">')
  .replace('<body>', '<body class="embedded-operations" data-operations-embedded="1" data-operations-page="__AIOPS_PAGE__">');
const output = `/* Generated by node tests/check-aiops-operations-bundle.js --write. Edit the source document and adapters, then regenerate. */
(function (global) {
  'use strict';
  var source = ${JSON.stringify(document)};
  global.AIOpsOperationsDocument = {
    create: function (page, baseURL) {
      var safeBase = String(baseURL).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
      return source.replace('__AIOPS_BASE__', safeBase).replace('__AIOPS_PAGE__', encodeURIComponent(page));
    }
  };
})(window);
`;
const target = path.join(root, 'aiops/operations-document.js');
if (process.argv.includes('--write')) fs.writeFileSync(target, output);
assert.equal(fs.readFileSync(target, 'utf8'), output, 'Operations bundle is stale. Run this check with --write.');
const context = { window: {} };
vm.createContext(context);
vm.runInContext(output, context);
for (const page of ['本体知识运营', '自定义看板', '消息通知']) {
  const html = context.window.AIOpsOperationsDocument.create(page, 'file:///workspace/dist/');
  assert(html.includes('data-operations-page="' + encodeURIComponent(page) + '"'));
  assert(html.includes('<base href="file:///workspace/dist/">'));
  assert(!/<script\b[^>]*\bsrc=/.test(html), 'No cross-file scripts inside the operations frame');
  assert(!/<link\b[^>]*rel="stylesheet"/.test(html), 'No cross-file styles inside the operations frame');
  for (const match of html.matchAll(/<script>([\s\S]*?)<\/script>/g)) new vm.Script(match[1]);
}
console.log('Passed: operations source/bundle parity; self-contained scripts and styles; local-file base URL; target-page configuration; complete script syntax.');
